    "serveQuick": "source fury/bin/activate\nfxbx serve stabilityai/TripoSR --port 8000",
    "python": "from pathlib import Path\nfrom shutil import copyfile\nimport json\nimport requests\n\nbase = \"http://127.0.0.1:8000\"\nconfig = requests.get(base + \"/demo/config\", timeout=30)\nconfig.raise_for_status()\npayload = config.json()[\"example\"]  # 패키지에 동봉된 이미지\nresponse = requests.post(base + '/demo/run', json=payload, timeout=600)\nresponse.raise_for_status()\nresult = response.json()\n\n# Python도 같은 NPU 서버에서 실행합니다. 파일은 현재 폴더에 저장합니다.\ndef save_media(value):\n    if isinstance(value, dict):\n        for item in value.values():\n            save_media(item)\n    elif isinstance(value, list):\n        for item in value:\n            save_media(item)\n    elif isinstance(value, str) and len(value) < 4096 and \"\\n\" not in value:\n        source = Path(value)\n        if source.suffix.lower() in {\".png\", \".jpg\", \".glb\", \".obj\", \".ply\", \".safetensors\"} and source.is_file():\n            target = Path.cwd() / source.name\n            if source.resolve() != target.resolve():\n                copyfile(source, target)\n            print(target.resolve())\n\nsave_media(result)\ntext = json.dumps(result, ensure_ascii=False, indent=2)\nif len(text) > 2000:\n    Path(\"result.json\").write_text(text + \"\\n\", encoding=\"utf-8\")\n    print(Path(\"result.json\").resolve())\nelse:\n    print(text)\n",
    "serveNote": "",
    "detailSetup": "python -m venv fury\nsource fury/bin/activate\npython -m pip install --index-url https://download.pytorch.org/whl/cpu torch==2.10.0+cpu\npython -m pip install --upgrade \"fxbx[weights]==0.9.5\" furiosa-torch==2026.4.0 furiosa-tcc==2026.4.0 requests huggingface-hub trimesh scikit-image xatlas moderngl pillow\nfxbx run stabilityai/TripoSR --sample -o result.json",
    "detailServe": "python -m venv fury\nsource fury/bin/activate\npython -m pip install --index-url https://download.pytorch.org/whl/cpu torch==2.10.0+cpu\npython -m pip install --upgrade \"fxbx[weights]==0.9.5\" furiosa-torch==2026.4.0 furiosa-tcc==2026.4.0 requests huggingface-hub trimesh scikit-image xatlas moderngl pillow\nfxbx serve stabilityai/TripoSR --port 8000"
